const input = $input.first().json;
const content = input.output ?? input;
const slides = content.slides ?? [];
const issues = [];

if (!content.topic) {
  issues.push("Missing lesson topic");
}

if (!Array.isArray(slides) || slides.length !== 4) {
  issues.push("Expected exactly 4 slides");
}

let totalDuration = 0;

for (let i = 0; i < slides.length; i++) {
  const slide = slides[i];
  const duration = Number(slide.duration_seconds);

  if (!slide.voiceover?.trim()) {
    issues.push(`Missing voiceover in slide ${i + 1}`);
  }

  if (!slide.on_screen_text?.trim()) {
    issues.push(`Missing text in slide ${i + 1}`);
  }

  if (!slide.image_prompt?.trim()) {
    issues.push(`Missing image prompt in slide ${i + 1}`);
  }

  if (!Number.isFinite(duration) || duration <= 0) {
    issues.push(`Invalid duration in slide ${i + 1}`);
  } else {
    totalDuration += duration;
  }
}

if (totalDuration < 30 || totalDuration > 60) {
  issues.push("Video duration must be 30-60 seconds");
}

const passed = issues.length === 0;

return [{
  json: {
    ...content,
    total_duration_seconds: totalDuration,
    internal_quality_check: {
      ...content.internal_quality_check,
      ready_for_publishing: false
    },
    quality_gate: {
      passed,
      issues,
      status: passed
        ? "CONTENT_CHECK_PASSED"
        : "CONTENT_CHECK_FAILED"
    }
  }
}];

const items = $input.all();
const slides = $('Split Out').all();

if (items.length !== 4 || slides.length !== 4) {
  throw new Error('Expected exactly 4 slides');
}

const elements = [];
let currentTime = 0;

for (let i = 0; i < items.length; i++) {
  const media = items[i].json;
  const slide = slides[i].json;

  const imageUrl = media.secure_url_1;
  const audioUrl = media.secure_url_2;
  const duration = Number(media.duration_2);

  if (!imageUrl || !audioUrl) {
    throw new Error(`Missing media for slide ${i + 1}`);
  }

  if (!Number.isFinite(duration) || duration <= 0) {
    throw new Error(`Invalid duration for slide ${i + 1}`);
  }

  // Background image
  elements.push({
    type: 'image',
    source: imageUrl,
    time: currentTime,
    duration: duration,
    width: '100%',
    height: '100%',
    fit: 'cover'
  });

  // Voiceover
  elements.push({
    type: 'audio',
    source: audioUrl,
    time: currentTime,
    duration: duration
  });

  // Brand heading
  elements.push({
    type: 'text',
    text: 'SECURITY+ KSA',
    time: currentTime,
    duration: duration,
    x: '50%',
    y: '10%',
    width: '85%',
    height: '6%',
    font_family: 'Cairo',
    font_weight: '700',
    font_size: '4 vmin',
    fill_color: '#00C2FF',
    x_alignment: '50%',
    y_alignment: '50%'
  });

  // Educational text
  elements.push({
    type: 'text',
    text: String(slide.on_screen_text || ''),
    time: currentTime,
    duration: duration,
    x: '50%',
    y: '65%',
    width: '80%',
    height: '30%',
    font_family: 'Cairo',
    font_weight: '700',
    font_size: '5 vmin',
    fill_color: '#FFFFFF',
    x_alignment: '50%',
    y_alignment: '50%',
    animations: [
      {
        type: 'fade',
        time: 0,
        duration: 0.4
      }
    ]
  });

  // Account username
  elements.push({
    type: 'text',
    text: '@SecurityPlusKSA',
    time: currentTime,
    duration: duration,
    x: '45%',
    y: '85%',
    width: '65%',
    height: '5%',
    font_family: 'Cairo',
    font_size: '3 vmin',
    fill_color: '#00C2FF',
    x_alignment: '50%'
  });

  // Slide number
  elements.push({
    type: 'text',
    text: `0${i + 1}/04`,
    time: currentTime,
    duration: duration,
    x: '85%',
    y: '10%',
    width: '15%',
    height: '5%',
    font_family: 'Cairo',
    font_size: '2.5 vmin',
    fill_color: '#FFFFFF',
    x_alignment: '50%'
  });

  currentTime += duration;
}

// Duration validation
const durationCheck =
  currentTime >= 30 && currentTime <= 60;

return [
  {
    json: {
      total_duration_seconds: currentTime,
      slide_count: items.length,
      duration_check: durationCheck,
      render_script: {
        output_format: 'mp4',
        width: 1080,
        height: 1920,
        frame_rate: 30,
        elements: elements
      }
    }
  }
];

const items = $input.all();

for (const item of items) {
  if (!item.binary?.data) {
    throw new Error("Missing ElevenLabs audio file");
  }

  item.binary.audio = item.binary.data;
  delete item.binary.data;
}

return items;
